-- Approved PostgreSQL/Supabase schema. Apply only to a verified direct Supabase project.
create extension if not exists pgcrypto;
create table if not exists public.users (id uuid primary key references auth.users(id) on delete cascade,email text,name text,created_at timestamptz not null default now());
create table if not exists public.organizations (id uuid primary key default gen_random_uuid(),name text not null,tier text not null default 'starter' check(tier in ('starter','pro','full_time_investor','team','enterprise')),created_at timestamptz not null default now());
create table if not exists public.organization_memberships (organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,role text not null default 'member' check(role in ('admin','member')),joined_at timestamptz not null default now(),primary key(organization_id,user_id));
create table if not exists public.properties (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),address text,city text,state text,zip text,county text,latitude numeric,longitude numeric,property_type text,beds numeric,baths numeric,living_area integer,lot_size integer,year_built integer,listing_status text,days_on_market integer,estimated_value numeric,data_quality_score numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.property_fields (id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,field_name text not null,value jsonb,classification text not null check(classification in ('SOURCE_DATA','NORMALIZED_DATA','CALCULATED_DATA','AI_ESTIMATE','USER_INPUT','UNKNOWN')),source text,confidence text,updated_at timestamptz not null default now());
create table if not exists public.owners (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid not null references public.properties(id) on delete cascade,name text,entity_type text,mailing_address text,ownership_duration_years integer,estimated_equity numeric,mortgage_balance numeric,tax_delinquent boolean,foreclosure_status text,owner_occupied boolean,authorized_phone text,authorized_email text,data_quality_score numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.comps (id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id),comparable_property_id uuid,distance_miles numeric,distance_score numeric,sale_date date,recency_score numeric,similarity_score numeric,quality_score numeric,adjusted_price numeric,weight numeric,outlier_classification text,inclusion_reason text,exclusion_reason text,created_at timestamptz not null default now());
create table if not exists public.deal_analyses (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid not null references public.properties(id),result jsonb not null,assumptions jsonb not null,calculated_at timestamptz not null default now(),calculated_by uuid references public.users(id));
create table if not exists public.motivation_signals (id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id),signal_type text not null,evidence text,evidence_value jsonb,source text,source_confidence text,signal_state text not null check(signal_state in ('VERIFIED','POSSIBLE','UNKNOWN')),weight numeric,detected_at timestamptz not null default now(),expires_at timestamptz);
create table if not exists public.deals (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid references public.properties(id),owner_id uuid references public.owners(id),current_stage text not null default 'NEW' check(current_stage in ('NEW','QUALIFIED','RESEARCHING','CONTACTED','FOLLOW_UP','NEGOTIATING','OFFER_MADE','CONTRACT_PENDING','UNDER_CONTRACT','BUYER_SEARCH','BUYER_INTERESTED','BUYER_SELECTED','ASSIGNMENT_PENDING','ASSIGNED','CLOSING','CLOSED','DEAD','CANCELLED')),purchase_price numeric,contract_price numeric,closing_date date,assignment_fee_target numeric,selected_buyer_id uuid,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.deal_stage_history (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),from_stage text,to_stage text not null,notes text,transitioned_by uuid references public.users(id),transitioned_at timestamptz not null default now());
create table if not exists public.deal_snapshots (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),snapshot_type text not null default 'contract_execution',analysis_data jsonb not null,created_at timestamptz not null default now());
create table if not exists public.sellers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),property_id uuid references public.properties(id),owner_id uuid references public.owners(id),name text,email text,phone text,mailing_address text,status text,notes text,next_follow_up_date timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.outreach (id uuid primary key default gen_random_uuid(),seller_id uuid not null references public.sellers(id),contact_method text not null,message text,subject text,status text not null,timestamp timestamptz not null default now());
create table if not exists public.offers (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),seller_id uuid references public.sellers(id),offer_amount numeric,proposed_terms jsonb,closing_date date,contingencies jsonb,status text not null,timestamps jsonb not null default '{}');
create table if not exists public.buyers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,company text,email text,phone text,mailing_address text,status text not null default 'new' check(status in ('new','active','qualified','inactive','blacklisted')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buyer_criteria (buyer_id uuid primary key references public.buyers(id) on delete cascade,markets jsonb not null default '[]',zip_codes jsonb not null default '[]',property_types jsonb not null default '[]',price_range jsonb,arv_range jsonb,investment_strategy text,rehab_tolerance text,minimum_spread numeric,cash_only boolean,financing_available boolean,updated_at timestamptz not null default now());
create table if not exists public.buyer_matches (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),buyer_id uuid not null references public.buyers(id),match_score numeric not null,match_reasons jsonb not null,failed_criteria jsonb not null,confidence text not null,configuration jsonb not null,created_at timestamptz not null default now(),unique(deal_id,buyer_id));
create table if not exists public.buyer_distributions (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),buyer_id uuid not null references public.buyers(id),response_status text not null,interest_level text,sent_at timestamptz,opened_at timestamptz,buyer_response_text text,created_at timestamptz not null default now());
create table if not exists public.buyer_offers (id uuid primary key default gen_random_uuid(),distribution_id uuid references public.buyer_distributions(id),deal_id uuid not null references public.deals(id),buyer_id uuid not null references public.buyers(id),offer_amount numeric,closing_date date,contingencies jsonb,financing text,status text not null,created_at timestamptz not null default now());
create table if not exists public.contracts (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),parties jsonb not null,contract_price numeric,execution_date date,closing_date date,contract_type text not null,status text not null,terms jsonb,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.documents (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),contract_id uuid references public.contracts(id),deal_id uuid references public.deals(id),document_type text not null,title text not null,storage_key text not null,version integer not null,uploaded_by uuid references public.users(id),metadata jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,storage_key,version));
create table if not exists public.transactions (id uuid primary key default gen_random_uuid(),deal_id uuid not null references public.deals(id),buyer_id uuid references public.buyers(id),exit_strategy text not null check(exit_strategy in ('assignment')),assignment_fee_target numeric,assignment_fee_actual numeric,contract_price numeric,closing_date date,actual_closing_price numeric,status text not null,closing_costs numeric,final_net numeric,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.tasks (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),deal_id uuid references public.deals(id),user_id uuid references public.users(id),task_type text not null,description text not null,due_date timestamptz,status text not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.activities (id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),deal_id uuid references public.deals(id),user_id uuid references public.users(id),activity_type text not null,description text not null,details jsonb,created_at timestamptz not null default now());
create table if not exists public.usage (id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),user_id uuid references public.users(id),metric text not null,quantity integer not null default 1,created_at timestamptz not null default now());
create table if not exists public.audit_logs (id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id),entity_type text not null,entity_id uuid,action text not null,old_value jsonb,new_value jsonb,changed_by uuid references public.users(id),request_id uuid,changed_at timestamptz not null default now());
create or replace function public.prevent_audit_mutation() returns trigger language plpgsql as $$ begin raise exception 'audit_logs are immutable'; end; $$;
drop trigger if exists audit_logs_immutable on public.audit_logs; create trigger audit_logs_immutable before update or delete on public.audit_logs for each row execute function public.prevent_audit_mutation();
alter table public.organizations enable row level security; alter table public.properties enable row level security; alter table public.deals enable row level security; alter table public.buyers enable row level security; alter table public.documents enable row level security; alter table public.audit_logs enable row level security;
create policy "members read properties" on public.properties for select using (organization_id in (select organization_id from public.organization_memberships where user_id=auth.uid()));
create policy "members read deals" on public.deals for select using (organization_id in (select organization_id from public.organization_memberships where user_id=auth.uid()));
create policy "members read buyers" on public.buyers for select using (organization_id in (select organization_id from public.organization_memberships where user_id=auth.uid()));
create policy "members read documents" on public.documents for select using (organization_id in (select organization_id from public.organization_memberships where user_id=auth.uid()));
create policy "members read audit logs" on public.audit_logs for select using (organization_id in (select organization_id from public.organization_memberships where user_id=auth.uid()));

